namespace Sim.Core.Scoring;

/// <summary>One entry of the in-game glossary: what the word means, and how this game uses it.</summary>
public sealed record GlossaryTerm(string Term, string Category, string Short, string Game, string? Page = null, string[]? See = null, string[]? Aka = null);

/// <summary>
/// The searchable glossary behind F2. Definitions are short and use the game's own numbers where they differ from a textbook; each entry can point to the
/// page where the thing is changed or shown. UI-free so that tests can check cross-references and page names.
/// </summary>
public static class Glossary
{
    public static readonly string[] Categories = { "Output and jobs", "Prices and money", "Public finances", "Tax and benefits", "Trade and the world", "Society and politics", "How the game works" };
    public static readonly string[] Pages = { "Dashboard", "Budget", "Monetary", "Policies", "Investment", "Sectors", "Trade", "Society", "Forecast", "World map", "Cabinet", "Rankings", "Journal", "Report" };

    static GlossaryTerm T(string term, string cat, string brief, string game, string? page = null, string[]? see = null, string[]? aka = null) => new(term, cat, brief, game, page, see, aka);

    public static readonly IReadOnlyList<GlossaryTerm> Terms = new[]
    {
        // ---- output and jobs ----
        T("Real GDP", "Output and jobs", "The value of everything produced in a year, adjusted for price changes.", "Growth is real GDP against a year ago. The Dashboard indexes it to 100 at the start of the game so you can see the path.", "Dashboard", new[] { "Nominal GDP", "Potential output" }),
        T("Nominal GDP", "Output and jobs", "GDP at today's prices, with no adjustment for inflation.", "Taxes, debt ratios and the interest bill are measured against nominal GDP, which is why inflation quietly shrinks debt ratios.", null, new[] { "Real GDP" }),
        T("Potential output", "Output and jobs", "What the economy can produce without pushing prices up: set by capital, labour, skills and technology.", "Six sectors build it from capital, labour, human capital, productivity and the quality of public assets. Investment lifts it slowly.", "Sectors", new[] { "Output gap", "TFP" }),
        T("Output gap", "Output and jobs", "How far actual output is above (positive) or below (negative) potential.", "A negative gap means slack: unemployment above its natural rate and pressure on prices to fall. A large positive gap overheats the economy and raises inflation.", "Dashboard", new[] { "Potential output", "Recession" }),
        T("Recession", "Output and jobs", "A period when output falls and sits below potential.", "The clock can stop for you when one starts (Settings, pause triggers). Approval, tax revenue and the deficit all react within a few months.", "Dashboard", new[] { "Output gap", "Automatic stabilisers" }),
        T("TFP", "Output and jobs", "Total factor productivity: output not explained by more capital or labour, such as better technology and organisation.", "It grows slowly, faster with research spending, infrastructure and skills, and slower under unrest. It is the main source of long-run growth.", "Sectors", new[] { "Potential output", "Human capital" }, new[] { "Productivity" }),
        T("Human capital", "Output and jobs", "The skills and health of the workforce.", "Built by education and health spending over many years; it raises productivity and lowers the natural rate of unemployment.", "Budget", new[] { "TFP" }),
        T("Unemployment rate", "Output and jobs", "The share of the labour force without a job that is looking for one.", "It follows the output gap (Okun's law) and drifts toward the natural rate. Its level feeds approval, the benefit bill and unrest.", "Dashboard", new[] { "NAIRU", "Okun's law" }),
        T("NAIRU", "Output and jobs", "The natural rate of unemployment: the level at which inflation neither speeds up nor slows.", "Starts at the country's calibrated rate and moves with your choices: a higher minimum wage relative to earnings, higher payroll tax and more generous or longer unemployment benefits raise it; better skills and labour-market reforms lower it. It also drifts slowly toward actual unemployment (hysteresis).", "Dashboard", new[] { "Unemployment rate", "Replacement rate" }, new[] { "Natural rate of unemployment", "Natural rate" }),
        T("Okun's law", "Output and jobs", "A rule of thumb linking the output gap to unemployment: when output runs below potential, unemployment rises above its natural rate.", "In the model unemployment is pulled toward the natural rate minus half the output gap, so a gap of minus 4% leaves it about two points above the natural rate.", null, new[] { "Output gap", "NAIRU" }),
        T("Hysteresis", "Output and jobs", "When a downturn leaves lasting damage: long-term unemployed lose skills and the natural rate rises.", "Unemployment more than a point above the natural rate builds a stock of long-term unemployed who drain away at about a fifth a year. The stock lifts the natural rate, by up to two points, and by more where unions protect insiders. The Society page shows both. Avoiding a slump is worth more than the output lost in it.", "Society", new[] { "NAIRU", "Collective bargaining" }),
        T("Labour share", "Output and jobs", "The share of national income paid as wages rather than profits.", "Follows bargaining power and falls in deep slumps and when real pay falls behind prices. A higher share lifts household spending a little and lowers measured inequality.", "Society", new[] { "Collective bargaining", "Gini" }),
        T("Participation rate", "Output and jobs", "The share of working-age people who are in work or looking for it.", "Marginal rates and benefit withdrawal move it: a high effective marginal rate on low earners keeps people out of work; raising the pension age keeps older people in.", "Budget", new[] { "Marginal tax rate", "Pension age" }),
        T("Fiscal multiplier", "Output and jobs", "How much output changes for each pound of extra government spending or tax cut.", "Not one number: it depends on who gets the money (poorer households spend more of it), on slack in the economy and on the interest-rate response. Unemployment and means-tested benefits lift demand most; pensions least; corporation-tax cuts barely at all in the first year.", "Budget", new[] { "Marginal propensity to consume", "Crowding out" }),
        T("Marginal propensity to consume", "Output and jobs", "The share of an extra pound of income that a household spends rather than saves.", "Poorer households spend more of each extra pound. The game scales a benefit's effect on demand by who receives it: unemployment ×1.30, means-tested ×1.25, housing ×1.20, disability ×1.12, child ×1.10, pensions ×0.85.", "Budget", new[] { "Fiscal multiplier" }, new[] { "MPC" }),
        T("Crowding out", "Output and jobs", "Government borrowing pushing up interest rates and squeezing private investment.", "Higher deficits and debt raise the sovereign spread and the yield, which lifts loan rates for firms.", null, new[] { "Yield", "Sovereign spread" }),
