        T("Inflation target", "Prices and money", "The inflation rate the central bank aims for.", "Usually 2%. The Taylor rule raises the policy rate when inflation is above it.", "Monetary", new[] { "Taylor rule" }),
        T("Inflation expectations", "Prices and money", "What households and firms expect inflation to be: they feed into wage and price setting.", "Anchored expectations make inflation easy to control; expectations drift when the central bank loses credibility, for example by monetising deficits.", "Monetary", new[] { "Credibility", "Inflation" }),
        T("Credibility", "Prices and money", "How far people believe the central bank will do what it takes to hit its target.", "A credible bank can calm inflation with small rate moves. Pinning the rate against the rule, or printing money for the deficit, wears it away; it rebuilds slowly.", "Monetary", new[] { "Inflation expectations", "Monetisation" }),
        T("Wage-price spiral", "Prices and money", "Prices rise, workers claim higher pay to catch up, firms pass the cost on, and prices rise again.", "Bargained pay answers the part of a price shock beyond a one-point band; about half the premium reaches prices. Bigger and longer where union coverage is high, smaller where the central bank is credible. The Society page shows the pp it adds to inflation.", "Society", new[] { "Collective bargaining", "Credibility", "Inflation expectations" }, new[] { "Wage spiral", "Second-round effects" }),
        T("Policy rate", "Prices and money", "The short-term interest rate set by the central bank.", "Under the default rule it follows the Taylor rule, limited to half a point a month. Pin it on the Monetary page and the slider shows the 3, 6 and 12-month effect before you commit.", "Monetary", new[] { "Taylor rule", "Real interest rate" }, new[] { "Interest rate", "Bank rate" }),
        T("Taylor rule", "Prices and money", "A rule of thumb that sets the policy rate from inflation and the output gap.", "The cabinet's default: rate = neutral rate + inflation + a weight on the inflation gap + a weight on the output gap.", "Monetary", new[] { "Policy rate", "Neutral rate" }),
        T("Neutral rate", "Prices and money", "The interest rate that neither speeds up nor slows the economy once inflation is at target.", "It is roughly the long-run real rate plus target inflation. Rates above it are tight; below it, loose.", "Monetary", new[] { "Real interest rate" }),
