        T("Sovereign spread", "Prices and money", "The extra interest investors demand to lend to this government rather than a safe benchmark.", "It widens with debt above 60% of GDP, deficits above 4%, inflation above 5%, low stability, corruption, thin reserves and contagion from other countries. A wide spread feeds back into the interest bill.", "Dashboard", new[] { "Yield", "Debt-to-GDP" }),
        T("Zero lower bound", "Prices and money", "The point where the policy rate cannot usefully fall further.", "Rates can go slightly negative in the model, but further cuts add little, which is why deep recessions near zero need fiscal support.", "Monetary", new[] { "Policy rate" }, new[] { "ZLB" }),
        T("Monetisation", "Prices and money", "The central bank financing the government's deficit by creating money.", "It lowers borrowing costs for a while and wrecks credibility, so inflation expectations and the exchange rate pay for it later.", "Monetary", new[] { "Credibility" }),
