    static readonly Dictionary<string, GlossaryTerm> ByName = Terms.SelectMany(t => new[] { t.Term }.Concat(t.Aka ?? Array.Empty<string>()).Select(n => (n, t))).GroupBy(p => p.n, StringComparer.OrdinalIgnoreCase).ToDictionary(g => g.Key, g => g.First().t, StringComparer.OrdinalIgnoreCase);

    public static GlossaryTerm? Find(string name) => ByName.TryGetValue(name, out var t) ? t : null;

    /// <summary>Terms matching <paramref name="query"/>, best first: exact name, name prefix, other name or alias hit, then the wording of the explanation. Empty query lists everything alphabetically.</summary>
    public static List<GlossaryTerm> Search(string query, string? category = null)
    {
        var pool = Terms.Where(t => category == null || t.Category == category);
        string q = (query ?? "").Trim();
        if (q.Length == 0) return pool.OrderBy(t => t.Term, StringComparer.OrdinalIgnoreCase).ToList();
        var words = q.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        int Score(GlossaryTerm t)
        {
            string name = t.Term;
            if (name.Equals(q, StringComparison.OrdinalIgnoreCase)) return 100;
            if (t.Aka?.Any(a => a.Equals(q, StringComparison.OrdinalIgnoreCase)) == true) return 95;
            if (name.StartsWith(q, StringComparison.OrdinalIgnoreCase)) return 80;
            if (t.Aka?.Any(a => a.StartsWith(q, StringComparison.OrdinalIgnoreCase)) == true) return 75;
            if (name.Contains(q, StringComparison.OrdinalIgnoreCase)) return 60;
            if (t.Aka?.Any(a => a.Contains(q, StringComparison.OrdinalIgnoreCase)) == true) return 55;
            string body = t.Short + " " + t.Game;
            if (words.All(w => body.Contains(w, StringComparison.OrdinalIgnoreCase))) return 20;
            return 0;
        }
        return pool.Select(t => (t, s: Score(t))).Where(p => p.s > 0).OrderByDescending(p => p.s).ThenBy(p => p.t.Term, StringComparer.OrdinalIgnoreCase).Select(p => p.t).ToList();
    }
}
